/*
 * V8 ApiEngine
 * ApiEngineKey: shouhoudd_zhipai
 * Version: v1.0.4
 * Function:
 * - 对单条或多条待指派售后任务统一设置服务人员、联系电话、指派人和指派时间；兼容 Id/Ids，最多200条，全部校验通过后统一更新。
 * - 操作者与目标人员从当前租户主库复核；普通账号只能在同商家指派任意角色的启用人员，平台跨商家能力同时要求主库用户等级和有效已绑定角色等级。
 * - 人员姓名、电话和指派人快照以数据库为准，不接受客户端姓名、等级或商家作为授权事实。
 */

// 解析主库保存的角色绑定，仅角色Id参与权限，不相信缓存的角色名称与等级。
function boundRoleIds(value) {
  var source = value;
  if (typeof source === 'string') {
    try { source = JSON.parse(source); } catch (error) { source = source.split(','); }
  }
  if (source && source.length === undefined) source = [source];
  var result = [];
  var seen = Object.create(null);
  for (var i = 0; source && i < source.length; i++) {
    var item = source[i];
    var id = String(item && typeof item === 'object' ? item.Id || item.id || '' : item || '').trim();
    if (id && !seen[id]) { seen[id] = true; result.push(id); }
  }
  return result;
}

// 用户与角色均走当前接口事务，避免副本延迟或旧会话投影扩大跨商家能力。
function isPlatformAdministrator(user) {
  if (Number(user.Level) < 9999 || !isFinite(Number(user.Level))) return false;
  var roleIds = boundRoleIds(user.RoleIds);
  if (!roleIds.length) return false;
  var roleResult = V8.FormEngine.GetTableData('Sys_Role', {
    _Where: [['Id', 'In', roleIds], ['AND', 'IsDeleted', '=', 0]],
    _SelectFields: ['Id', 'Level', 'IsDeleted'], _PageIndex: 1, _PageSize: roleIds.length
  }, V8.DbTrans);
  if (!roleResult || Number(roleResult.Code) !== 1 || !roleResult.Data) return false;
  for (var i = 0; i < roleResult.Data.length; i++) {
    var role = roleResult.Data[i];
    if (roleIds.indexOf(String(role.Id || '')) >= 0 && Number(role.IsDeleted || 0) === 0 && Number(role.Level) >= 9999) return true;
  }
  return false;
}

var ids = [];
var idMap = Object.create(null);
var rawIds = V8.Param.Ids;
if (rawIds && typeof rawIds !== 'string' && rawIds.length !== undefined) {
  for (var i = 0; i < rawIds.length; i++) {
    var batchId = rawIds[i] ? String(rawIds[i]).trim() : '';
    if (batchId && !idMap[batchId]) {
      idMap[batchId] = true;
      ids.push(batchId);
    }
  }
}
if (V8.Param.Id) {
  var singleId = String(V8.Param.Id).trim();
  if (singleId && !idMap[singleId]) {
    idMap[singleId] = true;
    ids.push(singleId);
  }
}

var targetId = typeof V8.Param.ShouhouRYID === 'string' ? V8.Param.ShouhouRYID.trim() : '';
if (!ids.length || !targetId || targetId.length > 128 || /[\r\n]/.test(targetId)) {
  V8.Result = { Code: 0, Msg: '请选择售后任务和服务人员！' };
  return;
}
if (ids.length > 200) {
  V8.Result = { Code: 0, Msg: '单次最多指派200条售后任务！' };
  return;
}

if (!V8.CurrentUser || !V8.CurrentUser.Id) {
  V8.Result = { Code: 1001, Msg: '登录状态已失效，请重新登录！' };
  return;
}
var currentResult = V8.FormEngine.GetFormData('Sys_User', {
  Id: String(V8.CurrentUser.Id), _SelectFields: ['Id', 'Name', 'TenantId', 'Level', 'RoleIds', 'State', 'IsDeleted']
}, V8.DbTrans);
var currentUser = currentResult && Number(currentResult.Code) === 1 ? currentResult.Data : null;
if (!currentUser || String(currentUser.Id) !== String(V8.CurrentUser.Id) || Number(currentUser.State) !== 1 || Number(currentUser.IsDeleted || 0) !== 0) {
  V8.Result = { Code: 0, Msg: '当前账号已停用、删除或无法验证，请重新登录！' };
  return;
}
var targetResult = V8.FormEngine.GetFormData('Sys_User', {
  Id: targetId, _SelectFields: ['Id', 'Name', 'Account', 'Phone', 'TenantId', 'State', 'IsDeleted']
}, V8.DbTrans);
var targetUser = targetResult && Number(targetResult.Code) === 1 ? targetResult.Data : null;
if (!targetUser || String(targetUser.Id) !== targetId || Number(targetUser.State) !== 1 || Number(targetUser.IsDeleted || 0) !== 0) {
  V8.Result = { Code: 0, Msg: '所选服务人员已停用、删除或不存在，请重新选择！' };
  return;
}
var isPlatformAdmin = isPlatformAdministrator(currentUser);
var currentTenantId = String(currentUser.TenantId || '').trim();
var targetTenantId = String(targetUser.TenantId || '').trim();
if (!isPlatformAdmin && (!currentTenantId || targetTenantId !== currentTenantId)) {
  V8.Result = { Code: 0, Msg: '只能指派当前商家的服务人员！' };
  return;
}

// 先一次性读取并校验全部任务，再执行批量更新，避免循环查询和部分成功。
var taskResult = V8.FormEngine.GetTableData('Diy_ShouhouDD', {
  Ids: ids,
  _SelectFields: ['Id', 'Zhuangtai', 'ZhuangtaiZ', 'TenantId', 'IsDeleted'],
  _PageIndex: 1,
  _PageSize: ids.length
}, V8.DbTrans);
if (!taskResult || taskResult.Code != 1) {
  V8.Result = taskResult || { Code: 0, Msg: '读取售后任务失败！' };
  return;
}
var tasks = taskResult.Data || [];
if (tasks.length != ids.length) {
  V8.Result = { Code: 0, Msg: '部分售后任务不存在或已不可访问，请刷新列表后重试！' };
  return;
}

var invalidIds = [];
var seenTaskIds = Object.create(null);
for (var j = 0; j < tasks.length; j++) {
  var taskId = String(tasks[j].Id || '');
  if (!idMap[taskId] || seenTaskIds[taskId] || Number(tasks[j].IsDeleted || 0) !== 0 || (!isPlatformAdmin && String(tasks[j].TenantId || '').trim() !== currentTenantId)) {
    V8.Result = { Code: 0, Msg: '部分售后任务不属于当前商家或已不可用，请刷新后重试！' };
    return;
  }
  seenTaskIds[taskId] = true;
  if (Number(tasks[j].ZhuangtaiZ) != 1) {
    invalidIds.push(String(tasks[j].Id));
  }
}
if (invalidIds.length) {
  V8.Result = {
    Code: 0,
    Msg: '所选任务中有' + invalidIds.length + '条不是待指派状态，请刷新列表后重新选择！'
  };
  return;
}

var assignTime = V8.Action.GetDateTimeNow();
var updateRows = [];
for (var k = 0; k < tasks.length; k++) {
  var updateRow = {
    FormEngineKey: 'Diy_ShouhouDD',
    Id: tasks[k].Id,
    ZhipaiSJ: assignTime,
    ShouhouRYID: targetUser.Id,
    ShouhouRY: targetUser.Name || targetUser.Account || '',
    ShouhouRYDH: targetUser.Phone || '',
    ZhipaiR: currentUser.Name || '',
    ZhipaiRID: currentUser.Id
  };
  updateRows.push(updateRow);
}

var result = V8.FormEngine.UptTableData(updateRows, V8.DbTrans);
if (!result || result.Code != 1) {
  V8.Result = result || { Code: 0, Msg: '售后任务指派失败！' };
  return;
}

V8.Result = {
  Code: 1,
  Data: {
    Count: updateRows.length,
    Ids: ids
  },
  Msg: '已成功指派' + updateRows.length + '条售后任务！'
};

/*
 * V8 ApiEngine
 * ApiEngineKey: get-sysUser-list
 * Version: v1.1.4
 * Function:
 * - 小程序通讯录安全查询：从主库复核有效账号的商家和等级，普通账号仅查询当前商家，主库 Level >= 9999 可跨商家并按商家名称搜索；已授权 Sys_User 模块支持全部/启用/禁用状态、所属组织多选与兼职组织 JSON 成员 OR 筛选，旧联系人调用默认启用。GetCardDefinition 精确回读授权卡片配置、安全字段字典与组织控件配置，列表按配置供数并解析角色/部门名称。
 */

function toList(value) {
  var result = [];
  if (value === undefined || value === null) return result;
  var source = value;
  if (typeof source === 'string') {
    var text = source.trim();
    if (!text) return result;
    try {
      source = JSON.parse(text);
    } catch (ignoreJson) {
      source = text.split(',');
    }
  }
  try {
    for (var i = 0; i < source.length; i++) result.push(source[i]);
  } catch (ignoreList) {}
  return result;
}

function addUniqueText(target, value) {
  var text = value === undefined || value === null ? '' : String(value).trim();
  if (text && target.indexOf(text) < 0) target.push(text);
}

function toStringList(value) {
  var result = [];
  var list = toList(value);
  for (var i = 0; i < list.length; i++) {
    var item = list[i];
    if (item && typeof item === 'object') addUniqueText(result, item.Id || item.id || item.Value || item.value);
    else addUniqueText(result, item);
  }
  return result;
}

function parseRoleIds(value) {
  var result = [];
  if (value === undefined || value === null) return result;
  var source = value;
  if (typeof source === 'string') {
    var text = source.trim();
    if (!text) return result;
    try {
      source = JSON.parse(text);
    } catch (ignoreJson) {
      source = text.split(',');
    }
  }
  var list = toList(source);
  if (!list.length && source && typeof source === 'object') list = [source];
  for (var i = 0; i < list.length; i++) {
    var item = list[i];
    if (item && typeof item === 'object') addUniqueText(result, item.Id || item.id || item.Value || item.value);
    else addUniqueText(result, item);
  }
  return result;
}

function appendRoleFilter(where, values) {
  if (!values.length) return;
  for (var i = 0; i < values.length; i++) {
    var roleId = String(values[i] || '').replace(/[%_]/g, '').trim();
    if (!roleId) continue;
    where.push({
      AndOr: i === 0 ? 'AND' : 'OR',
      GroupStart: i === 0,
      GroupEnd: i === values.length - 1,
      Name: 'RoleIds',
      Value: '%' + roleId + '%',
      Type: 'Like'
    });
  }
}

function normalizeOperation(value) {
  var operation = String(value || '=').trim().toLowerCase();
  if (operation === '==' || operation === 'equal') return '=';
  if (operation === '!=' || operation === 'notequal') return '<>';
  if (operation === 'like') return 'Like';
  if (operation === 'in') return 'In';
  if (operation === '>=' || operation === '<=' || operation === '>' || operation === '<' || operation === '=' || operation === '<>') {
    return operation;
  }
  return '=';
}

function safeText(value, maxLength) {
  var text = value === undefined || value === null ? '' : String(value).trim();
  if (text.length > maxLength) text = text.substring(0, maxLength);
  return text;
}

// 通讯录展示的固定安全边界。客户端配置和查询参数均不能扩大到密码、密钥等字段。
var contactFields = {};
var contactFieldNames = 'Id,Name,Account,Phone,Email,RoleIds,DeptName,DeptId,DeptIds,DeptCode,Level,No,TenantName,Avatar,PublicAvatar,CreateTime,UpdateTime,State,Sex,UserType,Jobs,JobLevel,Remark'.split(',');
for (var contactIndex = 0; contactIndex < contactFieldNames.length; contactIndex++) contactFields[contactFieldNames[contactIndex]] = true;

function jsonObject(value) {
  if (!value) return {};
  if (typeof value !== 'string') return value;
  try { return JSON.parse(value); } catch (ignore) { return {}; }
}

function copyKeys(source, keys) {
  var target = {};
  for (var i = 0; i < keys.length; i++) {
    if (source[keys[i]] !== undefined && source[keys[i]] !== null) target[keys[i]] = source[keys[i]];
  }
  return target;
}

function safeConfiguredFields(value, fields) {
  var result = [];
  var list = toList(value);
  for (var i = 0; i < list.length; i++) {
    var item = list[i];
    if (!item) continue;
    var references = typeof item === 'object' ? [item.Id, item.FieldId, item.Name, item.Field] : [item];
    for (var j = 0; j < fields.length; j++) {
      var matched = false;
      for (var r = 0; r < references.length; r++) {
        if (references[r] && (String(fields[j].Id) === String(references[r]) || String(fields[j].Name).toLowerCase() === String(references[r]).toLowerCase())) matched = true;
      }
      if (matched) {
        var entry = typeof item === 'object' ? copyKeys(item, ['Label', 'Format']) : {};
        entry.Id = fields[j].Id;
        entry.Name = fields[j].Name;
        if (/^[A-Za-z][A-Za-z0-9_]{0,63}$/.test(item.AsName || '') && !contactFields[item.AsName] &&
            !/password|passwd|pwd|secret|token|apikey|openid|unionid/i.test(item.AsName)) entry.AsName = item.AsName;
        // 通讯录直接查询物理字段，不执行配置中的 SQL、别名表达式或 V8。
        result.push(entry);
        break;
      }
    }
  }
  return result;
}

function safeCardSchema(value, fields) {
  var schema = jsonObject(value);
  schema = jsonObject(schema.ViewSchema || schema);
  var views = toList(schema.Views);
  var result = [];
  for (var i = 0; i < views.length; i++) {
    var view = views[i];
    if (String(view.Scene).toLowerCase() !== 'card') continue;
    var layout = jsonObject(view.Layout);
    var source = jsonObject(layout.Card);
    var card = copyKeys(source, ['HideIndex', 'ShowCreateTime', 'ShowUpdateTime']);
    var scalar = ['AvatarTextField', 'TitleField', 'SummaryField', 'ImageField', 'PeriodField'];
    for (var j = 0; j < scalar.length; j++) {
      var matches = safeConfiguredFields([source[scalar[j]]], fields);
      if (matches.length) card[scalar[j]] = matches[0].Name;
    }
    var groups = ['StatusFields', 'TopFields', 'SubtitleFields', 'RightFields', 'Fields', 'MetaFields', 'BottomFields', 'TagFields'];
    for (var k = 0; k < groups.length; k++) card[groups[k]] = safeConfiguredFields(source[groups[k]], fields);
    var safeView = copyKeys(view, ['Id', 'Name', 'Scene', 'Device', 'Enabled', 'Priority', 'RoleIds']);
    safeView.Layout = { Card: card };
    result.push(safeView);
  }
  return { SchemaVersion: '1.0', Views: result };
}

async function directoryDefinition(currentUser) {
  var tableResult = await V8.FormEngine.GetDiyTableModel('sys_user', V8.OsClient);
  if (!tableResult || Number(tableResult.Code) !== 1 || !tableResult.Data) return { Code: 0, Msg: '通讯录表单配置加载失败' };
  var table = tableResult.Data;
  // 使用平台目录的既有鉴权原子，身份由当前请求解析，不接受客户端身份/租户覆盖。
  var menusResult = V8.Method.ManageSystemDirectory({ Domain: 'SysMenu', Action: 'GetSysMenuStep', Param: {} });
  if (!menusResult || Number(menusResult.Code) !== 1) return { Code: 0, Msg: '通讯录菜单授权读取失败' };
  var pending = toList(menusResult.Data);
  var matches = [];
  var requestedId = safeText(V8.Param._SysMenuId, 100);
  var requestedKey = safeText(V8.Param.ModuleEngineKey || 'Sys_User', 100).toLowerCase();
  var menuCursor = 0;
  while (menuCursor < pending.length) {
    var candidate = pending[menuCursor++];
    var children = toList(candidate._Child || candidate.children);
    for (var c = 0; c < children.length; c++) pending.push(children[c]);
    if (String(candidate.DiyTableId) !== String(table.Id) || Number(candidate.IsDeleted || 0) !== 0 ||
        Number(candidate.Display) === 0 || Number(candidate.AppDisplay) === 0) continue;
    if (requestedId && String(candidate.Id) !== requestedId) continue;
    if (String(candidate.ModuleEngineKey || '').toLowerCase() !== requestedKey) continue;
    matches.push(candidate);
  }
  if (matches.length !== 1) return { Code: 0, Msg: '通讯录模块不存在、配置不唯一或当前账号无权访问' };
  var menu = matches[0];
  var fieldResult = await V8.FormEngine.GetDiyFieldList({ TableId: table.Id, OsClient: V8.OsClient });
  if (!fieldResult || Number(fieldResult.Code) !== 1) return { Code: 0, Msg: '通讯录字段配置加载失败' };
  var raw = toList(fieldResult.Data);
  var fields = [];
  for (var f = 0; f < raw.length; f++) {
    var field = raw[f];
    if (contactFields[field.Name] !== true) continue;
    var bindRoles = toStringList(field.BindRole);
    if (bindRoles.length) {
      var grantedRoles = parseRoleIds(currentUser.RoleIds);
      var canRead = false;
      for (var r = 0; r < bindRoles.length; r++) if (grantedRoles.indexOf(bindRoles[r]) >= 0) canRead = true;
      if (!canRead) continue;
    }
    var safeField = copyKeys(field, ['Id', 'Name', 'Label', 'Component', 'Type', 'Sort', 'Visible', 'AppVisible', 'BindRole']);
    var config = jsonObject(field.Config);
    var staticOptions = config.DataSource === 'Data' || config.DataSource === 'KeyValue';
    safeField.Data = (staticOptions ? toList(field.Data) : []).map(function(option) {
      return typeof option === 'object' ? copyKeys(option, ['Id', 'Name', 'Key', 'Value', 'Label', 'Text', 'value', 'label']) : option;
    });
    safeField.Config = copyKeys(config, ['SelectSaveField', 'SelectLabel', 'Multiple']);
    if (field.Component === 'Department') {
      safeField.Config.Department = copyKeys(config.Department || {}, ['Multiple', 'EmitPath', 'Filterable']);
    }
    safeField.Config.DataSource = 'Data';
    fields.push(safeField);
  }
  // 审计字段不一定注册在 diy_field，但仍允许后台用字段名配置。
  var audits = ['CreateTime', 'UpdateTime'];
  for (var a = 0; a < audits.length; a++) {
    var found = false;
    for (var x = 0; x < fields.length; x++) if (fields[x].Name === audits[a]) found = true;
    if (!found) fields.push({ Id: audits[a], Name: audits[a], Label: a ? '更新时间' : '创建时间', Component: 'DateTime', Visible: 1, AppVisible: 1 });
  }
  var safeMenu = copyKeys(menu, ['Id', 'Name', 'DiyTableId', 'ModuleEngineKey', 'UpdateTime', 'ViewConfigVersion', 'ViewSchemaVersion', 'EnableViewSchema', 'PageSize']);
  safeMenu.DiyTableName = table.Name;
  var lists = ['MobileListFields', 'CardTitleTagFields', 'CardBottomTagFields', 'SelectFields', 'SearchFieldIds'];
  for (var m = 0; m < lists.length; m++) safeMenu[lists[m]] = safeConfiguredFields(menu[lists[m]], fields);
  safeMenu.ViewSchema = safeCardSchema(menu.ViewSchema, fields);
  return { Code: 1, Data: { Menu: safeMenu, Table: copyKeys(table, ['Id', 'Name', 'Description']), Fields: fields } };
}

return (async function() {
var currentUser = V8.CurrentUser || {};
if (!currentUser.Id) {
  return { Code: 1001, Data: null, DataCount: 0, Msg: '登录状态已失效，请重新登录' };
}

var userContext = V8.Db.FromSql(
  'SELECT TenantId, Level FROM Sys_User WHERE Id = @p0 AND IsDeleted = @p1 AND State = @p2'
)
  .AddInParameter('@p0', currentUser.Id)
  .AddInParameter('@p1', 0)
  .AddInParameter('@p2', 1)
  .First();
if (!userContext) return { Code: 0, Data: null, DataCount: 0, Msg: '当前账号已停用、删除或无法验证' };
var tenantId = userContext && userContext.TenantId ? String(userContext.TenantId).trim() : '';
var userLevel = userContext ? (parseInt(userContext.Level, 10) || 0) : 0;
var isPlatformAdmin = userLevel >= 9999;
if (!tenantId && !isPlatformAdmin) {
  return { Code: 0, Data: null, DataCount: 0, Msg: '当前账号未关联商家' };
}

var action = safeText(V8.Param.Action, 50);
if (action && action !== 'GetCardDefinition') return { Code: 0, Msg: '不支持的通讯录操作' };
var definition = null;
if (action || V8.Param._SysMenuId || V8.Param.ModuleEngineKey) {
  var definitionResult = await directoryDefinition(currentUser);
  if (Number(definitionResult.Code) !== 1) return definitionResult;
  definition = definitionResult.Data;
  if (action === 'GetCardDefinition') return definitionResult;
}

var pageIndex = parseInt(V8.Param._PageIndex, 10) || 1;
var pageSize = parseInt(V8.Param._PageSize, 10) || 20;
if (pageIndex < 1) pageIndex = 1;
if (pageSize < 1) pageSize = 20;
if (pageSize > 100) pageSize = 100;

var where = [{ Name: 'IsDeleted', Value: 0, Type: '=' }];
var clientFilters = toList(V8.Param._Where);
var hasStateFilter = clientFilters.some(function(item) { return item && (item.Name || item.name) === 'State'; });
// 已授权模块的“全部状态”包含启用和禁用；旧联系人调用仍默认只取启用人员。
if (!definition && !hasStateFilter) where.push({ AndOr: 'AND', Name: 'State', Value: 1, Type: '=' });
if (!isPlatformAdmin) {
  where.push({ AndOr: 'AND', Name: 'TenantId', Value: tenantId, Type: '=' });
}

var roleIds = toStringList(V8.Param.RoleIds);
var roleNames = toStringList(V8.Param.RoleNames);
var roleNameToId = {};
var roleWhere = [{ Name: 'IsDeleted', Value: 0, Type: '=' }];
if (!isPlatformAdmin) {
  roleWhere.push({ AndOr: 'AND', Name: 'TenantId', Value: tenantId, Type: '=' });
}
var roleResult = V8.FormEngine.GetTableData({
  FormEngineKey: 'Sys_Role',
  _Where: roleWhere,
  _SelectFields: ['Id', 'Name', 'Level', 'TenantId'],
  _OrderBy: 'Level',
  _OrderByType: 'DESC',
  _PageIndex: 1,
  _PageSize: 1000
});
var roles = roleResult && Number(roleResult.Code) === 1 && roleResult.Data ? roleResult.Data : [];
for (var roleIndex = 0; roleIndex < roles.length; roleIndex++) {
  var roleRow = roles[roleIndex];
  var roleName = safeText(roleRow.Name, 500);
  if (roleName && roleRow.Id) roleNameToId[roleName] = String(roleRow.Id);
}
if (!roleIds.length && roleNames.length) {
  for (var roleNameIndex = 0; roleNameIndex < roleNames.length; roleNameIndex++) {
    var requestedRoleId = roleNameToId[roleNames[roleNameIndex]];
    if (requestedRoleId) addUniqueText(roleIds, requestedRoleId);
  }
}

var allowedFilters = {
  Account: 'text',
  Name: 'text',
  Phone: 'text',
  Email: 'text',
  DeptName: 'text',
  DeptId: 'text',
  DeptIds: 'departments',
  State: 'state',
  RoleIds: 'role',
  Level: 'number',
  No: 'text',
  Remark: 'text',
  CreateTime: 'date',
  TenantName: 'text'
};
var partTimeDepartments = [];
for (var filterIndex = 0; filterIndex < clientFilters.length; filterIndex++) {
  var condition = clientFilters[filterIndex] || {};
  var fieldName = safeText(condition.Name || condition.name, 50);
  var kind = allowedFilters[fieldName];
  if (!kind) continue;
  if (fieldName === 'TenantName' && !isPlatformAdmin) continue;
  var operation = normalizeOperation(condition.Type || condition.type);
  var conditionValue = condition.Value;
  if (kind === 'state') {
    if (operation !== '=' && operation !== '<>' && operation !== 'In') return { Code: 0, Msg: '状态筛选方式无效' };
    var stateValues = operation === 'In' ? toList(conditionValue) : [conditionValue];
    if (!stateValues.length) return { Code: 0, Msg: '状态筛选值无效' };
    for (var s = 0; s < stateValues.length; s++) {
      if (String(stateValues[s]) !== '0' && String(stateValues[s]) !== '1') return { Code: 0, Msg: '状态筛选值无效' };
      stateValues[s] = Number(stateValues[s]);
    }
    where.push({ AndOr: 'AND', Name: 'State', Type: operation, Value: operation === 'In' ? stateValues : stateValues[0] });
    continue;
  }
  if (kind === 'departments') {
    if (operation !== '=' && operation !== 'In' && operation !== 'Like') return { Code: 0, Msg: '兼职组织筛选方式无效' };
    var departments;
    if (operation === 'Like') {
      try {
        var path = JSON.parse(String(conditionValue));
        departments = typeof path === 'string' ? [path] : [path[path.length - 1]];
      } catch (invalidPath) { return { Code: 0, Msg: '兼职组织筛选值无效' }; }
    } else departments = operation === 'In' ? toList(conditionValue) : [conditionValue];
    for (var d = 0; d < departments.length; d++) {
      var departmentId = String(departments[d] || '');
      if (!/^[a-zA-Z0-9-]{1,100}$/.test(departmentId)) return { Code: 0, Msg: '兼职组织筛选值无效' };
      addUniqueText(partTimeDepartments, departmentId);
    }
    continue;
  }
  if (kind === 'role') {
    var requestedRoles = toStringList(conditionValue);
    for (var requestedIndex = 0; requestedIndex < requestedRoles.length; requestedIndex++) {
      addUniqueText(roleIds, String(requestedRoles[requestedIndex]).replace(/[%_]/g, ''));
    }
    continue;
  }
  if (kind === 'number') {
    if (operation !== '=' && operation !== '>=' && operation !== '<=' && operation !== '>' && operation !== '<') continue;
    var numberValue = Number(conditionValue);
    if (!isFinite(numberValue)) continue;
    where.push({ AndOr: 'AND', Name: fieldName, Value: numberValue, Type: operation });
    continue;
  }
  if (kind === 'date') {
    if (operation !== '=' && operation !== '>=' && operation !== '<=' && operation !== '>' && operation !== '<') continue;
    var dateValue = safeText(conditionValue, 25);
    if (!/^\d{4}-\d{2}-\d{2}/.test(dateValue)) continue;
    where.push({ AndOr: 'AND', Name: fieldName, Value: dateValue, Type: operation });
    continue;
  }
  if (operation !== '=' && operation !== '<>' && operation !== 'Like' && operation !== 'In') continue;
  if (operation === 'In') {
    var inValues = toStringList(conditionValue);
    if (inValues.length) where.push({ AndOr: 'AND', Name: fieldName, Value: inValues, Type: 'In' });
    continue;
  }
  var textValue = safeText(conditionValue, 100);
  if (!textValue) continue;
  where.push({
    AndOr: 'AND',
    Name: fieldName,
    Value: operation === 'Like' ? '%' + textValue.replace(/%/g, '') + '%' : textValue,
    Type: operation
  });
}

// 同一字段的多个机构按任一匹配查询；JSON token 避免短 Id 匹配其它机构。
for (var p = 0; p < partTimeDepartments.length; p++) {
  where.push({ AndOr: p ? 'OR' : 'AND', GroupStart: p === 0, GroupEnd: p === partTimeDepartments.length - 1,
    Name: 'DeptIds', Type: 'Like', Value: '%' + JSON.stringify(partTimeDepartments[p]) + '%' });
}

var dateSearch = V8.Param._SearchDateTime || {};
var createTimeRange = toStringList(dateSearch.CreateTime);
if (createTimeRange.length >= 2) {
  var startTime = safeText(createTimeRange[0], 25);
  var endTime = safeText(createTimeRange[1], 25);
  if (/^\d{4}-\d{2}-\d{2}/.test(startTime) && /^\d{4}-\d{2}-\d{2}/.test(endTime)) {
    where.push({ AndOr: 'AND', Name: 'CreateTime', Value: startTime, Type: '>=' });
    where.push({ AndOr: 'AND', Name: 'CreateTime', Value: endTime, Type: '<=' });
  }
}

appendRoleFilter(where, roleIds);

var keyword = safeText(V8.Param.Keyword || V8.Param._Keyword || V8.Param.q || V8.Param.search, 50);
if (keyword) {
  where.push({ AndOr: 'AND', GroupStart: true, Name: 'Name', Value: '%' + keyword + '%', Type: 'Like' });
  where.push({ AndOr: 'OR', Name: 'DeptName', Value: '%' + keyword + '%', Type: 'Like' });
  where.push({ AndOr: 'OR', Name: 'Account', Value: '%' + keyword + '%', Type: 'Like' });
  where.push({ AndOr: 'OR', Name: 'Phone', Value: '%' + keyword + '%', Type: 'Like' });
  where.push({ AndOr: 'OR', Name: 'Email', Value: '%' + keyword + '%', Type: 'Like', GroupEnd: !isPlatformAdmin });
  // 商家名称只扩大平台管理员的关键词匹配，不改变普通账号固定商家过滤。
  if (isPlatformAdmin) where.push({ AndOr: 'OR', Name: 'TenantName', Value: '%' + keyword + '%', Type: 'Like', GroupEnd: true });
}

var allowedOrderFields = {
  Name: true,
  Account: true,
  Phone: true,
  DeptName: true,
  Level: true,
  No: true,
  CreateTime: true
};
var orderBy = safeText(V8.Param._OrderBy, 50);
if (!allowedOrderFields[orderBy]) orderBy = 'Name';
var orderType = String(V8.Param._OrderByType || '').toUpperCase() === 'DESC' ? 'DESC' : 'ASC';

var selectedFields = [
  'Id', 'Name', 'DeptName', 'Account', 'Phone', 'Email', 'RoleIds',
  'Level', 'No', 'TenantName', 'Avatar', 'PublicAvatar', 'CreateTime', 'State'
];
var requestedFields = toStringList(V8.Param._SelectFields);
for (var s = 0; s < requestedFields.length; s++) {
  var requested = requestedFields[s];
  if (contactFields[requested] !== true) continue;
  // 新版请求还需通过字段角色权限；未绑定菜单的旧调用维持固定字段集。
  if (!definition) continue;
  for (var d = 0; d < definition.Fields.length; d++) {
    if (definition.Fields[d].Name === requested) addUniqueText(selectedFields, requested);
  }
}
var result = V8.FormEngine.GetTableData({
  FormEngineKey: 'Sys_User',
  _Where: where,
  _SelectFields: selectedFields,
  _OrderBy: orderBy,
  _OrderByType: orderType,
  _PageIndex: pageIndex,
  _PageSize: pageSize
});

if (!result || Number(result.Code) !== 1) {
  return { Code: 0, Data: null, DataCount: 0, Msg: (result && result.Msg) || '通讯录人员加载失败' };
}

var roleIdToName = {};
for (var mapIndex = 0; mapIndex < roles.length; mapIndex++) {
  if (roles[mapIndex] && roles[mapIndex].Id) {
    roleIdToName[String(roles[mapIndex].Id)] = safeText(roles[mapIndex].Name, 500);
  }
}
var users = result.Data || [];
for (var userIndex = 0; userIndex < users.length; userIndex++) {
  var user = users[userIndex];
  var userRoleIds = parseRoleIds(user.RoleIds);
  var userRoleNames = [];
  for (var userRoleIndex = 0; userRoleIndex < userRoleIds.length; userRoleIndex++) {
    addUniqueText(userRoleNames, roleIdToName[userRoleIds[userRoleIndex]]);
  }
  user.RoleName = userRoleNames.join('、');
  user.DepartmentName = user.DeptName || '';
  user.Avatar = user.PublicAvatar || user.Avatar || '';
  user._CardDisplay = { RoleIds: user.RoleName, DeptId: user.DeptName || '' };
  if (definition) {
    var aliasLists = ['MobileListFields', 'CardTitleTagFields', 'CardBottomTagFields'];
    for (var al = 0; al < aliasLists.length; al++) {
      var aliases = definition.Menu[aliasLists[al]] || [];
      for (var ai = 0; ai < aliases.length; ai++) {
        if (!aliases[ai].AsName) continue;
        user[aliases[ai].AsName] = user[aliases[ai].Name];
        if (user._CardDisplay[aliases[ai].Name] !== undefined) user._CardDisplay[aliases[ai].AsName] = user._CardDisplay[aliases[ai].Name];
      }
    }
  }
}

return {
  Code: 1,
  Data: users,
  DataCount: result.DataCount || 0,
  DataAppend: {
    Scope: isPlatformAdmin ? 'Platform' : 'Tenant'
  },
  Msg: ''
};
})();
